import React, { useEffect, useState } from "react"
import { collection, query, where, getDocs, orderBy, Timestamp } from "firebase/firestore"
import { db } from "../../../firebase/config"
import { format } from "date-fns"
import { Client, NewClientData, Vehicle, NewVehicleData, updateClient, addVehicle, removeVehicle } from "../../../hooks/useClients"
import { useToast } from "../../../context/ToastContext"

interface ServiceRecord {
  id: string
  date: Date
  serviceTypes: string[]
  customServiceDescription: string
  billableAmount: number
  taxGST: number
  taxQST: number
  status: string
  vehicleId: string
}

function fmt(n: number) {
  return `$ ${n.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

function VehicleHistory({ clientId, vehicleId }: { clientId: string; vehicleId: string }) {
  const [records, setRecords] = useState<ServiceRecord[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!db) { setLoading(false); return }
    getDocs(
      query(
        collection(db, "serviceTickets"),
        where("clientId", "==", clientId),
        where("vehicleId", "==", vehicleId),
        orderBy("createdAt", "desc")
      )
    ).then(snap => {
      setRecords(snap.docs.map(d => {
        const data = d.data()
        return {
          id: d.id,
          date: (data.createdAt as Timestamp).toDate(),
          serviceTypes: Array.isArray(data.serviceTypes) ? data.serviceTypes : data.serviceType ? [data.serviceType] : [],
          customServiceDescription: data.customServiceDescription ?? "",
          billableAmount: data.billableAmount ?? 0,
          taxGST: data.taxGST ?? 0,
          taxQST: data.taxQST ?? 0,
          status: data.status,
          vehicleId: data.vehicleId,
        }
      }))
    }).finally(() => setLoading(false))
  }, [clientId, vehicleId])

  if (loading) {
    return <div className="h-4 bg-gray-100 rounded animate-pulse mt-2" />
  }

  if (records.length === 0) {
    return <p className="text-xs text-gray-400 mt-2">No service history for this vehicle.</p>
  }

  return (
    <div className="mt-2 space-y-1.5">
      {records.map(r => {
        const label = r.serviceTypes.includes("custom")
          ? r.customServiceDescription || "Custom Service"
          : r.serviceTypes.map(s => s.replace(/-/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase())).join(", ")
        const total = r.billableAmount + r.taxGST + r.taxQST
        return (
          <div key={r.id} className="flex items-center justify-between text-xs text-gray-600 py-1 border-b border-gray-100 last:border-0">
            <div className="flex items-center gap-2 min-w-0">
              <span className="text-gray-400 flex-shrink-0">{format(r.date, "MMM d, yyyy")}</span>
              <span className="truncate capitalize">{label}</span>
            </div>
            <div className="flex items-center gap-2 flex-shrink-0 ml-2">
              <span className="font-mono">{fmt(total)}</span>
              <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-medium ${
                r.status === "completed" ? "bg-green-100 text-green-700" : "bg-yellow-100 text-yellow-700"
              }`}>
                {r.status}
              </span>
            </div>
          </div>
        )
      })}
    </div>
  )
}

interface Props {
  client: Client
  onClose: () => void
  onUpdated: (updated: Client) => void
}

interface FormErrors {
  name?: string
  phone?: string
  email?: string
}

function validate(f: NewClientData): FormErrors {
  const errors: FormErrors = {}
  if (!f.name.trim() || f.name.trim().length < 2) errors.name = "Name must be at least 2 characters"
  if (!f.phone.trim() || !/^[\d\s\-()+]+$/.test(f.phone.trim())) errors.phone = "Enter a valid phone number"
  if (f.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email.trim())) errors.email = "Enter a valid email address"
  return errors
}

const CURRENT_YEAR = new Date().getFullYear()

interface VehicleFormState {
  make: string; model: string; year: string; color: string; notes: string
}
interface VehicleFormErrors {
  make?: string; model?: string; year?: string; notes?: string
}

function validateVehicle(f: VehicleFormState): VehicleFormErrors {
  const errors: VehicleFormErrors = {}
  if (!f.make.trim()) errors.make = "Required"
  if (!f.model.trim()) errors.model = "Required"
  const y = parseInt(f.year, 10)
  if (!f.year || isNaN(y) || y < 1950 || y > CURRENT_YEAR + 1)
    errors.year = `1950 – ${CURRENT_YEAR + 1}`
  if (f.notes.length > 200) errors.notes = "Max 200 chars"
  return errors
}

export default function ClientDetailModal({ client, onClose, onUpdated }: Props) {
  const { showToast } = useToast()

  // ── Info form ──
  const [form, setForm] = useState<NewClientData>({
    name: client.name,
    phone: client.phone,
    email: client.email,
    address: client.address,
  })
  const [errors, setErrors] = useState<FormErrors>({})
  const [saving, setSaving] = useState(false)

  const isDirty =
    form.name !== client.name ||
    form.phone !== client.phone ||
    form.email !== client.email ||
    form.address !== client.address

  async function handleSave() {
    const errs = validate(form)
    setErrors(errs)
    if (Object.keys(errs).length > 0) return
    setSaving(true)
    try {
      await updateClient(client.id, form)
      const updated: Client = {
        ...client,
        ...form,
        updatedAt: new Date(),
      }
      onUpdated(updated)
      showToast("Client updated", "success")
    } catch {
      showToast("Failed to save", "error")
    } finally {
      setSaving(false)
    }
  }

  // ── Vehicle form ──
  const [vehicles, setVehicles] = useState<Vehicle[]>(client.vehicles)
  const [deletingVehicleId, setDeletingVehicleId] = useState<string | null>(null)
  const [expandedHistoryId, setExpandedHistoryId] = useState<string | null>(null)
  const [showVehicleForm, setShowVehicleForm] = useState(false)
  const [vehicleForm, setVehicleForm] = useState<VehicleFormState>({
    make: "", model: "", year: "", color: "", notes: "",
  })
  const [vehicleErrors, setVehicleErrors] = useState<VehicleFormErrors>({})
  const [savingVehicle, setSavingVehicle] = useState(false)

  async function handleRemoveVehicle(vehicleId: string) {
    setDeletingVehicleId(vehicleId)
    try {
      await removeVehicle(client.id, vehicleId, vehicles)
      const updatedVehicles = vehicles.filter(v => v.vehicleId !== vehicleId)
      setVehicles(updatedVehicles)
      onUpdated({ ...client, vehicles: updatedVehicles })
      showToast("Vehicle removed", "success")
    } catch {
      showToast("Failed to remove vehicle", "error")
    } finally {
      setDeletingVehicleId(null)
    }
  }

  function setVf(field: keyof VehicleFormState, value: string) {
    setVehicleForm(prev => ({ ...prev, [field]: value }))
    setVehicleErrors(prev => ({ ...prev, [field]: undefined }))
  }

  async function handleAddVehicle() {
    const errs = validateVehicle(vehicleForm)
    setVehicleErrors(errs)
    if (Object.keys(errs).length > 0) return
    setSavingVehicle(true)
    try {
      const vData: NewVehicleData = {
        make: vehicleForm.make.trim(),
        model: vehicleForm.model.trim(),
        year: parseInt(vehicleForm.year, 10),
        color: vehicleForm.color.trim(),
        notes: vehicleForm.notes.trim(),
      }
      const newVehicle = await addVehicle(client.id, vData)
      const updatedVehicles = [...vehicles, newVehicle]
      setVehicles(updatedVehicles)
      onUpdated({ ...client, vehicles: updatedVehicles })
      setVehicleForm({ make: "", model: "", year: "", color: "", notes: "" })
      setShowVehicleForm(false)
      showToast("Vehicle added", "success")
    } catch {
      showToast("Failed to add vehicle", "error")
    } finally {
      setSavingVehicle(false)
    }
  }

  // Close on Escape
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose()
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [onClose])

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Overlay */}
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />

      {/* Modal */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 flex-shrink-0">
          <h2 className="font-semibold text-gray-800">{client.name}</h2>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-700 text-xl leading-none transition-colors"
            aria-label="Close"
          >
            ✕
          </button>
        </div>

        {/* Scrollable body */}
        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-6">

          {/* ── Client info ── */}
          <section>
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">
              Contact Information
            </h3>
            <div className="space-y-3">
              {(
                [
                  { id: "cd-name",    label: "Full Name",   key: "name",    type: "text",  required: true  },
                  { id: "cd-phone",   label: "Phone",       key: "phone",   type: "tel",   required: true  },
                  { id: "cd-email",   label: "Email",       key: "email",   type: "email", required: false },
                  { id: "cd-address", label: "Address",     key: "address", type: "text",  required: false },
                ] as const
              ).map(({ id, label, key, type, required }) => (
                <div key={key}>
                  <label htmlFor={id} className="block text-xs font-medium text-gray-600 mb-1">
                    {label} {required && <span className="text-red-500">*</span>}
                  </label>
                  <input
                    id={id}
                    type={type}
                    value={form[key]}
                    onChange={e => {
                      setForm(prev => ({ ...prev, [key]: e.target.value }))
                      setErrors(prev => ({ ...prev, [key]: undefined }))
                    }}
                    className={`w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                      errors[key as keyof FormErrors] ? "border-red-400" : "border-gray-300"
                    }`}
                  />
                  {errors[key as keyof FormErrors] && (
                    <p className="text-xs text-red-500 mt-0.5">{errors[key as keyof FormErrors]}</p>
                  )}
                </div>
              ))}
            </div>

            <div className="flex justify-end mt-4">
              <button
                onClick={handleSave}
                disabled={!isDirty || saving}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                {saving ? "Saving…" : "Save Changes"}
              </button>
            </div>
          </section>

          {/* ── Vehicles ── */}
          <section>
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
                Vehicles ({vehicles.length})
              </h3>
              {!showVehicleForm && (
                <button
                  onClick={() => setShowVehicleForm(true)}
                  className="text-xs text-blue-600 hover:text-blue-700 font-medium transition-colors"
                >
                  + Add Vehicle
                </button>
              )}
            </div>

            {vehicles.length === 0 && !showVehicleForm && (
              <p className="text-sm text-gray-400">No vehicles registered.</p>
            )}

            <div className="space-y-2">
              {vehicles.map(v => (
                <div
                  key={v.vehicleId}
                  className="flex items-start gap-3 p-3 rounded-lg border border-gray-100 bg-gray-50"
                >
                  <span className="text-lg mt-0.5">🚗</span>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <p className="text-sm font-medium text-gray-800">
                        {v.year} {v.make} {v.model}
                        {v.color ? <span className="font-normal text-gray-500"> — {v.color}</span> : null}
                      </p>
                      <button
                        onClick={() => setExpandedHistoryId(expandedHistoryId === v.vehicleId ? null : v.vehicleId)}
                        className="text-xs text-blue-500 hover:text-blue-700 transition-colors flex-shrink-0"
                      >
                        {expandedHistoryId === v.vehicleId ? "▲ Hide history" : "▼ History"}
                      </button>
                    </div>
                    {v.notes && (
                      <p className="text-xs text-gray-400 mt-0.5 truncate">{v.notes}</p>
                    )}
                    {expandedHistoryId === v.vehicleId && (
                      <VehicleHistory clientId={client.id} vehicleId={v.vehicleId} />
                    )}
                  </div>
                  <button
                    onClick={() => {
                      if (window.confirm(`Remove ${v.year} ${v.make} ${v.model}?`)) {
                        handleRemoveVehicle(v.vehicleId)
                      }
                    }}
                    disabled={deletingVehicleId === v.vehicleId}
                    className="text-gray-300 hover:text-red-500 transition-colors flex-shrink-0 disabled:opacity-40 text-lg leading-none mt-0.5"
                    title="Remove vehicle"
                    aria-label="Remove vehicle"
                  >
                    {deletingVehicleId === v.vehicleId ? (
                      <span className="w-4 h-4 border-2 border-red-300 border-t-transparent rounded-full animate-spin inline-block" />
                    ) : "✕"}
                  </button>
                </div>
              ))}
            </div>

            {/* Add vehicle form */}
            {showVehicleForm && (
              <div className="mt-3 border border-gray-200 rounded-xl p-4 space-y-3 bg-gray-50">
                <p className="text-xs font-semibold text-gray-600">New Vehicle</p>

                <div className="grid grid-cols-2 gap-3">
                  {(["make", "model"] as const).map(field => (
                    <div key={field}>
                      <label className="block text-xs font-medium text-gray-600 mb-1 capitalize">
                        {field} <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        value={vehicleForm[field]}
                        onChange={e => setVf(field, e.target.value)}
                        className={`w-full border rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white ${
                          vehicleErrors[field] ? "border-red-400" : "border-gray-300"
                        }`}
                      />
                      {vehicleErrors[field] && (
                        <p className="text-xs text-red-500 mt-0.5">{vehicleErrors[field]}</p>
                      )}
                    </div>
                  ))}
                  <div>
                    <label className="block text-xs font-medium text-gray-600 mb-1">
                      Year <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="number"
                      value={vehicleForm.year}
                      onChange={e => setVf("year", e.target.value)}
                      min={1950}
                      max={CURRENT_YEAR + 1}
                      className={`w-full border rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white ${
                        vehicleErrors.year ? "border-red-400" : "border-gray-300"
                      }`}
                    />
                    {vehicleErrors.year && (
                      <p className="text-xs text-red-500 mt-0.5">{vehicleErrors.year}</p>
                    )}
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-600 mb-1">Color</label>
                    <input
                      type="text"
                      value={vehicleForm.color}
                      onChange={e => setVf("color", e.target.value)}
                      className="w-full border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-medium text-gray-600 mb-1">Notes</label>
                  <input
                    type="text"
                    value={vehicleForm.notes}
                    onChange={e => setVf("notes", e.target.value)}
                    placeholder="Optional"
                    className={`w-full border rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white ${
                      vehicleErrors.notes ? "border-red-400" : "border-gray-300"
                    }`}
                  />
                  {vehicleErrors.notes && (
                    <p className="text-xs text-red-500 mt-0.5">{vehicleErrors.notes}</p>
                  )}
                </div>

                <div className="flex gap-2 justify-end">
                  <button
                    onClick={() => {
                      setShowVehicleForm(false)
                      setVehicleErrors({})
                      setVehicleForm({ make: "", model: "", year: "", color: "", notes: "" })
                    }}
                    className="px-3 py-1.5 border border-gray-200 text-gray-600 text-xs rounded-lg hover:bg-white transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleAddVehicle}
                    disabled={savingVehicle}
                    className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-xs font-medium rounded-lg transition-colors disabled:opacity-50"
                  >
                    {savingVehicle ? "Saving…" : "Add Vehicle"}
                  </button>
                </div>
              </div>
            )}
          </section>

          {/* ── Meta ── */}
          <section className="text-xs text-gray-400 space-y-0.5 pb-1">
            <p>Created: {client.createdAt.toLocaleDateString("en-CA", { year: "numeric", month: "short", day: "numeric" })}</p>
            <p>Last updated: {client.updatedAt.toLocaleDateString("en-CA", { year: "numeric", month: "short", day: "numeric" })}</p>
            <p className="font-mono text-gray-300">ID: {client.id}</p>
          </section>
        </div>
      </div>
    </div>
  )
}
