import React, { useState, useEffect } from "react"
import { graphql } from "gatsby"
import {
  collection,
  getDocs,
  orderBy,
  query as fsQuery,
  Timestamp,
} from "firebase/firestore"
import { db } from "../../firebase/config"
import { useRequireAuth } from "../../hooks/useRequireAuth"
import { Client } from "../../hooks/useClients"
import AdminLayout from "../../components/admin/AdminLayout"
import ClientForm from "../../components/admin/Clients/ClientForm"
import ClientDetailModal from "../../components/admin/Clients/ClientDetailModal"

const PAGE_SIZE = 20

export default function AdminClients() {
  const { currentUser, loading } = useRequireAuth()
  const [clients, setClients] = useState<Client[]>([])
  const [fetching, setFetching] = useState(true)
  const [page, setPage] = useState(0)
  const [showNew, setShowNew] = useState(false)
  const [selectedClient, setSelectedClient] = useState<Client | null>(null)

  async function fetchClients() {
    if (!db) return
    setFetching(true)
    try {
      const snap = await getDocs(
        fsQuery(collection(db, "clients"), orderBy("name"))
      )
      const data: Client[] = snap.docs.map(d => {
        const raw = d.data()
        return {
          id: d.id,
          name: raw.name,
          phone: raw.phone,
          email: raw.email ?? "",
          address: raw.address ?? "",
          vehicles: raw.vehicles ?? [],
          portalTokens: raw.portalTokens ?? [],
          createdAt: (raw.createdAt as Timestamp).toDate(),
          updatedAt: (raw.updatedAt as Timestamp).toDate(),
        }
      })
      setClients(data)
    } finally {
      setFetching(false)
    }
  }

  useEffect(() => {
    fetchClients()
  }, [])

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!currentUser) return null

  const paged = clients.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)
  const totalPages = Math.ceil(clients.length / PAGE_SIZE)

  return (
    <AdminLayout currentPath="/admin/clients">
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-xl font-bold text-gray-800">Clients</h1>
        <button
          onClick={() => setShowNew(true)}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
        >
          + New Client
        </button>
      </div>

      {/* New client inline form */}
      {showNew && (
        <div className="bg-white rounded-xl shadow-sm p-6 mb-6 max-w-lg">
          <h2 className="text-sm font-semibold text-gray-700 mb-4">New Client</h2>
          <ClientForm
            onSaved={client => {
              setClients(prev => [client, ...prev])
              setShowNew(false)
            }}
            onBack={() => setShowNew(false)}
          />
        </div>
      )}

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm overflow-hidden">
        {fetching ? (
          <div className="flex items-center justify-center py-16">
            <div className="w-6 h-6 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : clients.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-gray-400 gap-2">
            <p className="text-sm">No clients yet.</p>
            <button
              onClick={() => setShowNew(true)}
              className="text-sm text-blue-600 hover:text-blue-700 font-medium transition-colors"
            >
              + Add your first client
            </button>
          </div>
        ) : (
          <>
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 text-left">
                  <th className="px-4 py-3 font-semibold text-gray-500 text-xs uppercase tracking-wide">Name</th>
                  <th className="px-4 py-3 font-semibold text-gray-500 text-xs uppercase tracking-wide">Phone</th>
                  <th className="px-4 py-3 font-semibold text-gray-500 text-xs uppercase tracking-wide">Email</th>
                  <th className="px-4 py-3 font-semibold text-gray-500 text-xs uppercase tracking-wide">Vehicles</th>
                </tr>
              </thead>
              <tbody>
                {paged.map(client => (
                  <tr
                    key={client.id}
                    onClick={() => setSelectedClient(client)}
                    className="border-b border-gray-50 hover:bg-gray-50 transition-colors cursor-pointer"
                  >
                    <td className="px-4 py-3 font-medium text-gray-800">{client.name}</td>
                    <td className="px-4 py-3 text-gray-600">{client.phone}</td>
                    <td className="px-4 py-3 text-gray-600">
                      {client.email || (
                        <span className="text-yellow-600 text-xs">No email</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-gray-600">{client.vehicles.length}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            {totalPages > 1 && (
              <div className="flex items-center justify-between px-4 py-3 border-t border-gray-100">
                <span className="text-xs text-gray-500">
                  {clients.length} clients · Page {page + 1} of {totalPages}
                </span>
                <div className="flex gap-2">
                  <button
                    onClick={() => setPage(p => Math.max(0, p - 1))}
                    disabled={page === 0}
                    className="px-3 py-1 text-xs border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50 transition-colors"
                  >
                    ← Prev
                  </button>
                  <button
                    onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
                    disabled={page === totalPages - 1}
                    className="px-3 py-1 text-xs border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50 transition-colors"
                  >
                    Next →
                  </button>
                </div>
              </div>
            )}
          </>
        )}
      </div>
      {selectedClient && (
        <ClientDetailModal
          client={selectedClient}
          onClose={() => setSelectedClient(null)}
          onUpdated={updated => {
            setClients(prev => prev.map(c => c.id === updated.id ? updated : c))
            setSelectedClient(updated)
          }}
        />
      )}
    </AdminLayout>
  )
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`
