import React, { useState } from "react"
import { createClient, NewClientData, Client } from "../../../hooks/useClients"

interface ClientFormProps {
  onSaved: (client: Client) => void
  onBack: () => void
}

interface FormErrors {
  name?: string
  phone?: string
  email?: string
}

function validate(fields: NewClientData): FormErrors {
  const errors: FormErrors = {}
  if (!fields.name || fields.name.trim().length < 2)
    errors.name = "Name must be at least 2 characters"
  if (!fields.phone || !/^[\d\s\-()+]+$/.test(fields.phone.trim()))
    errors.phone = "Enter a valid phone number"
  if (fields.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email.trim()))
    errors.email = "Enter a valid email address"
  return errors
}

export default function ClientForm({ onSaved, onBack }: ClientFormProps) {
  const [name, setName] = useState("")
  const [phone, setPhone] = useState("")
  const [email, setEmail] = useState("")
  const [address, setAddress] = useState("")
  const [errors, setErrors] = useState<FormErrors>({})
  const [saving, setSaving] = useState(false)

  async function handleSave() {
    const data: NewClientData = { name, phone, email, address }
    const errs = validate(data)
    setErrors(errs)
    if (Object.keys(errs).length > 0) return

    setSaving(true)
    try {
      const client = await createClient(data)
      onSaved(client)
    } catch {
      setErrors({ name: "Failed to save client. Please try again." })
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="flex flex-col gap-4">
      <div>
        <label htmlFor="cf-name" className="block text-xs font-medium text-gray-700 mb-1">
          Full Name <span className="text-red-500">*</span>
        </label>
        <input
          id="cf-name"
          type="text"
          value={name}
          onChange={e => setName(e.target.value)}
          className={`w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            errors.name ? "border-red-400" : "border-gray-300"
          }`}
          placeholder="Jean-Pierre Tremblay"
        />
        {errors.name && <p className="text-xs text-red-500 mt-1">{errors.name}</p>}
      </div>

      <div>
        <label htmlFor="cf-phone" className="block text-xs font-medium text-gray-700 mb-1">
          Phone <span className="text-red-500">*</span>
        </label>
        <input
          id="cf-phone"
          type="tel"
          value={phone}
          onChange={e => setPhone(e.target.value)}
          className={`w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            errors.phone ? "border-red-400" : "border-gray-300"
          }`}
          placeholder="514-555-0100"
        />
        {errors.phone && <p className="text-xs text-red-500 mt-1">{errors.phone}</p>}
      </div>

      <div>
        <label htmlFor="cf-email" className="block text-xs font-medium text-gray-700 mb-1">
          Email
          <span className="ml-2 text-xs font-normal text-blue-600">
            Required to send portal link to client (Phase 07)
          </span>
        </label>
        <input
          id="cf-email"
          type="email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          className={`w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            errors.email ? "border-red-400" : "border-gray-300"
          }`}
          placeholder="jean-pierre@example.com"
        />
        {errors.email && <p className="text-xs text-red-500 mt-1">{errors.email}</p>}
      </div>

      <div>
        <label htmlFor="cf-address" className="block text-xs font-medium text-gray-700 mb-1">
          Address
        </label>
        <input
          id="cf-address"
          type="text"
          value={address}
          onChange={e => setAddress(e.target.value)}
          className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="123 Rue Principale, Montréal, QC"
        />
      </div>

      <div className="flex gap-3 pt-2">
        <button
          onClick={onBack}
          className="flex-1 py-2 px-4 border border-gray-300 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-50 transition-colors"
        >
          ← Back
        </button>
        <button
          onClick={handleSave}
          disabled={saving}
          className="flex-1 py-2 px-4 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white text-sm font-medium rounded-lg transition-colors"
        >
          {saving ? "Saving…" : "Save & Continue →"}
        </button>
      </div>
    </div>
  )
}
